sequenceDiagram(name = "CollisionAvoidance") {
    val camera = lifeline(name = "Camera") { isActor = true }
    val radar = lifeline(name = "Radar") { isActor = true }
    val fusion = lifeline(name = "Fusion Unit")
    val assistant = lifeline(name = "Emergency Braking Assistant")
    val driver = lifeline(name = "Driver") { isActor = true }
    val control = lifeline(name = "Control Unit")
    val log = lifeline(name = "Diagnostic Log")

    message(from = camera, to = fusion, label = "measurement data")
    message(from = radar, to = fusion, label = "measurement data")
    message(from = fusion, to = assistant, label = "collision risk (TTC)")
    branch(guard = "[TTC < critical threshold]") {
        message(from = assistant, to = driver, label = "acoustic warning")
        message(from = assistant, to = control, label = "initiate braking")
        loop(guard = "[until vehicle stationary]") {
            message(from = assistant, to = control, label = "adjust brake pressure")
        }
        message(from = assistant, to = log, label = "record event")
    }
    branch(guard = "[TTC >= critical threshold]") {
        message(from = assistant, to = driver, label = "distance warning")
        message(from = assistant, to = log, label = "log risk")
    }
}

